package com.quincaisoft.branch.application;import com.quincaisoft.branch.api.*;import com.quincaisoft.branch.infrastructure.*;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import java.util.*;@Service public class DefaultBranchService implements BranchService{private final EntityManager em;private final ScopedTransactions tx;public DefaultBranchService(EntityManager em,ScopedTransactions tx){this.em=em;this.tx=tx;}public List<Item> list(){return tx.execute(()->em.createQuery("select r from BranchEntity r order by r.name,r.id",BranchEntity.class).getResultList().stream().map(r->new Item(r.id,r.name,r.timezone)).toList());}}